rng=np.random.default_rng(523)
n=50000
X=np.zeros((n,20)); X[:,0]=rng.uniform(-4.2,3,n); X[:,1:10]=rng.integers(0,2,(n,9)); X[:,10:]=rng.uniform(0,10,(n,10))
y=predict(X).reshape(-1)
knots={0:[-3,-1.5,0,1.5]}
for j in range(10,20):knots[j]=[2,4,6,8]
desc=[('const',)]
cols=[np.ones(n)]
for j in range(20):
 desc.append(('lin',j));cols.append(X[:,j])
for j,ks in knots.items():
 for k in ks:
  desc.append(('hinge',j,k));cols.append(np.maximum(X[:,j]-k,0))
for i in range(20):
 for j in range(i+1,20):
  desc.append(('prod',i,j));cols.append(X[:,i]*X[:,j])
D=np.column_stack(cols)
N=40000
b=np.linalg.lstsq(D[:N],y[:N],rcond=None)[0]
yh=D@b
for label,s in [('train',slice(0,N)),('test',slice(N,n))]:
 e=y[s]-yh[s];p=1/(1+np.exp(-y[s]));ph=1/(1+np.exp(-yh[s]))
 print(label,'rmse',np.sqrt(np.mean(e**2)),'R2',1-np.var(e)/np.var(y[s]),'prob MAE/rmse',np.mean(np.abs(p-ph)),np.sqrt(np.mean((p-ph)**2)),'abs error quantiles',np.quantile(np.abs(e),[.5,.9,.95,.99,1]))
print('main')
for d,c in zip(desc[:65],b[:65]):print(d,round(c,6))
imp=[]
for z,d in enumerate(desc):
 if d[0]=='prod':
  i,j=d[1:];imp.append((abs(b[z])*np.std(X[:,i])*np.std(X[:,j]),z))
print('top interactions')
for score,z in sorted(imp,reverse=True)[:55]:print(desc[z],round(b[z],7),round(score,5))

