rng=np.random.default_rng(523)
n=40000
X=np.zeros((n,20)); X[:,0]=rng.uniform(-4.2,3,n); X[:,1:10]=rng.integers(0,2,(n,9)); X[:,10:]=rng.uniform(0,10,(n,10))
y=predict(X).reshape(-1)
lo=np.array([-4.2]+[0]*19); scale=np.array([7.2]+[1]*9+[10]*10)
Z=(X-lo)/scale
ud=[];uc=[]
for j in range(20):
 ud.append((j,0.0));uc.append(Z[:,j])
 if j==0 or j>=10:
  for k in [.25,.5,.75]:
   ud.append((j,k));uc.append(np.maximum(Z[:,j]-k,0))
U=np.column_stack(uc);mean=np.mean(U,axis=0);U=U-mean
ds=[('c',)];cols=[np.ones(n)]
for a in range(len(ud)):ds.append(('u',a));cols.append(U[:,a])
for a in range(len(ud)):
 for b in range(a+1,len(ud)):
  if ud[a][0]!=ud[b][0]: ds.append(('p',a,b));cols.append(U[:,a]*U[:,b])
D=np.column_stack(cols);cols=[]
N=30000
sd=np.sqrt(np.mean(D[:N]**2,axis=0));D=D/sd
b=np.linalg.solve(D[:N].T@D[:N]+np.eye(D.shape[1])*1.0,D[:N].T@y[:N])
yh=D@b
print('basis count',D.shape)
for label,s in [('train',slice(0,N)),('test',slice(N,n))]:
 e=y[s]-yh[s];p=1/(1+np.exp(-y[s]));ph=1/(1+np.exp(-yh[s]))
 print(label,'rmse',np.sqrt(np.mean(e**2)),'R2',1-np.var(e)/np.var(y[s]),'prob MAE/rmse',np.mean(np.abs(p-ph)),np.sqrt(np.mean((p-ph)**2)),'abs error quantiles',np.quantile(np.abs(e),[.5,.9,.95,.99,1]))
groups={}
for a,d in enumerate(ds):
 if d[0]=='p':
  i,j=ud[d[1]][0],ud[d[2]][0]
  if (i,j) not in groups:groups[i,j]=[]
  groups[i,j].append(a)
print('top interaction group contribution SD')
imp=[]
for ij,inds in groups.items():
 c=D[N:,inds]@b[inds]
 imp.append((np.std(c),ij))
for score,ij in sorted(imp,reverse=True)[:60]:print(INPUTS[ij[0]],INPUTS[ij[1]],round(score,5))

